<div class="learning-editor manual-editor"><header class="editor-heading"><div><p class="eyebrow">Pengelolaan pembelajaran</p><h1>Edit Kuis Manual</h1><p class="lead">Edit soal untuk setiap pertemuan tanpa JSON dan tanpa AI.</p></div></header>
 <?php if(isset($_GET['saved'])): ?><div class="editor-alert success">Soal berhasil disimpan dan diperbarui di halaman siswa.</div><?php endif; ?>
 <form method="post" action="kuis_save.php" id="quizForm"><input type="hidden" name="csrf" value="<?= h($csrf) ?>"><input type="hidden" name="id" value="<?= h($id) ?>">
 <section class="editor-card"><div class="section-heading"><span class="step-number">01</span><div><h2>Pilih pertemuan</h2><p>Soal akan disimpan ke pertemuan yang dipilih.</p></div></div><label for="meeting">Pertemuan</label><select class="field" id="meeting"><?php foreach($d['materi'] as $m): ?><option value="<?= h($m['id']) ?>"<?= $id===$m['id']?' selected':'' ?>><?= h($m['id'].' · Pertemuan '.$m['sem'].' · '.$m['judul']) ?></option><?php endforeach; ?></select><p class="small">Materi: <strong><?= h($item['judul']) ?></strong></p></section>
 <section class="editor-card"><div class="section-heading"><span class="step-number">02</span><div><h2>Soal latihan</h2><p>Soal latihan yang ditampilkan sebelum kuis.</p></div></div><?php render_question($item['latihan']??[],'latihan',0); ?></section>
 <section class="editor-card"><div class="section-heading"><span class="step-number">03</span><div><h2>Daftar soal kuis</h2><p>Tambah, ubah, atau hapus soal pilihan ganda.</p></div></div><div id="questionsList" class="manual-stack"><?php foreach(($item['kuis']??[]) as $i=>$q) render_question($q,'kuis',$i); ?></div><button type="button" class="btn ghost" id="addQuestion">+ Tambah soal kuis</button></section>
 <div class="editor-actions"><button class="btn" type="submit">Simpan Kuis</button><a class="btn ghost" href="ai_kuis.php?id=<?= h($id) ?>">Buat soal dengan AI</a></div>
 </form>
</div>
<template id="questionTemplate"><div class="manual-panel question-row"><div class="manual-panel-head"><strong>Soal kuis baru</strong><button type="button" class="btn ghost remove-row">Hapus soal</button></div><label>Pertanyaan<textarea class="field" name="kuis_q[]" rows="3" required></textarea></label><div class="manual-grid options-grid"><?php for($i=0;$i<4;$i++): ?><label>Opsi <?= chr(65+$i) ?><input class="field" name="kuis_o[NEW][]" required></label><?php endfor; ?></div><label>Kunci jawaban<select class="field" name="kuis_a[]"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></label><label>Pembahasan<textarea class="field" name="kuis_w[]" rows="2"></textarea></label></div></template>
<script>
(()=>{const list=document.getElementById('questionsList');document.getElementById('meeting').addEventListener('change',e=>location.href='?id='+encodeURIComponent(e.target.value));document.getElementById('addQuestion').addEventListener('click',()=>{const box=document.createElement('div');box.innerHTML=document.getElementById('questionTemplate').innerHTML;const node=box.firstElementChild;const idx=list.querySelectorAll('.question-row').length;node.querySelectorAll('[name]').forEach(el=>el.name=el.name.replace('NEW',String(idx)));list.append(node);});list.addEventListener('click',e=>{const b=e.target.closest('.remove-row');if(b)b.closest('.question-row')?.remove();});})();
</script><?php guru_foot(); ?>